"""Low-level tax rate computation engine."""
from typing import Dict, Any

DEFAULT_TAX_JURISDICTIONS = {
    "standard": 0.20,
    "reduced": 0.10,
    "exempt": 0.0,
}

def get_rate_for_jurisdiction(code: str) -> float:
    return DEFAULT_TAX_JURISDICTIONS.get(code, 0.20)

def calculate_vat(net_cents: int, vat_rate: float) -> int:
    """Compute VAT in integer cents for given net amount.
    Applies half-up rounding (ties broken towards positive infinity) as specified
    in the pricing module's docstring for tax calculations.
    """
    # Python's int() truncates (rounds towards zero), and round() uses banker's
    # rounding (rounds halves to the nearest even number).
    # For positive numbers, adding 0.5 and then truncating achieves half-up rounding.
    return int(net_cents * vat_rate + 0.5)
